/* vkminer -- a Vulkan compute cryptocurrency miner.
 * SPDX-License-Identifier: GPL-3.0-or-later
 *
 * Scalar Tiger (Anderson and Biham, 1996), the original with 0x01 padding,
 * which is what x16rv2 runs. Little-endian 64-byte blocks, three 64-bit
 * chaining words, three passes of eight rounds over four 8x64 S-boxes.
 *
 * The S-boxes are generated by the designers' published procedure rather than
 * written out; the published vectors check it. The oracle the kernels are
 * tested against, so it stays plain.
 */

#include "core/tiger192.h"

#include <string.h>

static uint64_t tiger_t[1024];
static int tiger_t_ready;

#define T1( x )  tiger_t[(x)]
#define T2( x )  tiger_t[256 + (x)]
#define T3( x )  tiger_t[512 + (x)]
#define T4( x )  tiger_t[768 + (x)]

static unsigned tiger_byte( uint64_t x, int i )
{
    return (unsigned)( x >> ( 8 * i ) ) & 0xff;
}

static void tiger_round( uint64_t *a, uint64_t *b, uint64_t *c, uint64_t x,
                         uint64_t mul )
{
    *c ^= x;
    *a -= T1( tiger_byte( *c, 0 ) ) ^ T2( tiger_byte( *c, 2 ) )
        ^ T3( tiger_byte( *c, 4 ) ) ^ T4( tiger_byte( *c, 6 ) );
    *b += T4( tiger_byte( *c, 1 ) ) ^ T3( tiger_byte( *c, 3 ) )
        ^ T2( tiger_byte( *c, 5 ) ) ^ T1( tiger_byte( *c, 7 ) );
    *b *= mul;
}

static void tiger_pass( uint64_t *a, uint64_t *b, uint64_t *c,
                        const uint64_t x[8], uint64_t mul )
{
    tiger_round( a, b, c, x[0], mul );
    tiger_round( b, c, a, x[1], mul );
    tiger_round( c, a, b, x[2], mul );
    tiger_round( a, b, c, x[3], mul );
    tiger_round( b, c, a, x[4], mul );
    tiger_round( c, a, b, x[5], mul );
    tiger_round( a, b, c, x[6], mul );
    tiger_round( b, c, a, x[7], mul );
}

static void tiger_key_schedule( uint64_t x[8] )
{
    x[0] -= x[7] ^ 0xa5a5a5a5a5a5a5a5ull;
    x[1] ^= x[0];
    x[2] += x[1];
    x[3] -= x[2] ^ ( ~x[1] << 19 );
    x[4] ^= x[3];
    x[5] += x[4];
    x[6] -= x[5] ^ ( ~x[4] >> 23 );
    x[7] ^= x[6];
    x[0] += x[7];
    x[1] -= x[0] ^ ( ~x[7] << 19 );
    x[2] ^= x[1];
    x[3] += x[2];
    x[4] -= x[3] ^ ( ~x[2] >> 23 );
    x[5] ^= x[4];
    x[6] += x[5];
    x[7] -= x[6] ^ 0x0123456789abcdefull;
}

/* Passes with multipliers 5, 7 and 9, the chaining words rotating between
 * them, then the feed-forward.  */
static void tiger_compress( uint64_t h[3], const uint64_t block[8] )
{
    uint64_t x[8];
    uint64_t a = h[0], b = h[1], c = h[2];

    memcpy( x, block, sizeof x );
    tiger_pass( &a, &b, &c, x, 5 );
    tiger_key_schedule( x );
    tiger_pass( &c, &a, &b, x, 7 );
    tiger_key_schedule( x );
    tiger_pass( &b, &c, &a, x, 9 );

    h[0] = a ^ h[0];
    h[1] = b - h[1];
    h[2] = c + h[2];
}

static void tiger_decode( uint64_t x[8], const unsigned char *p )
{
    int i, j;

    for ( i = 0; i < 8; i++ ) {
        x[i] = 0;
        for ( j = 7; j >= 0; j-- )
            x[i] = ( x[i] << 8 ) | p[8 * i + j];
    }
}

static void tiger_swap_byte( uint64_t *p, uint64_t *q, int col )
{
    const int sh = 8 * col;
    const uint64_t m = 0xffull << sh;
    const uint64_t bp = *p & m, bq = *q & m;

    *p = ( *p & ~m ) | bq;
    *q = ( *q & ~m ) | bp;
}

/* The designers' generator: every byte column of every box starts as the
 * identity, then five passes swap entry i with the entry a byte of a running
 * Tiger state names. The state is compressed, under the boxes as they stand,
 * every third swap.  */
const uint64_t *tiger192_sboxes( void )
{
    static const char key[] =
        "Tiger - A Fast New Hash Function, by Ross Anderson and Eli Biham";
    uint64_t block[8];
    uint64_t state[3];
    int pass, i, sb, col, abc = 2;

    if ( tiger_t_ready )
        return tiger_t;

    for ( i = 0; i < 1024; i++ ) {
        tiger_t[i] = 0;
        for ( col = 0; col < 8; col++ )
            tiger_t[i] |= (uint64_t)( i & 0xff ) << ( 8 * col );
    }

    tiger_decode( block, (const unsigned char *)key );
    state[0] = 0x0123456789abcdefull;
    state[1] = 0xfedcba9876543210ull;
    state[2] = 0xf096a5b4c3b2e187ull;

    for ( pass = 0; pass < 5; pass++ )
        for ( i = 0; i < 256; i++ )
            for ( sb = 0; sb < 1024; sb += 256 ) {
                if ( ++abc == 3 ) {
                    abc = 0;
                    tiger_compress( state, block );
                }
                for ( col = 0; col < 8; col++ )
                    tiger_swap_byte( &tiger_t[sb + i],
                                     &tiger_t[sb + tiger_byte( state[abc], col )],
                                     col );
            }

    tiger_t_ready = 1;
    return tiger_t;
}

void tiger192_full( void *hash, const void *data, size_t len )
{
    const unsigned char *p = (const unsigned char *)data;
    const uint64_t bits = (uint64_t)len * 8u;
    unsigned char last[128];
    unsigned char *out = (unsigned char *)hash;
    uint64_t h[3] = {
        0x0123456789abcdefull, 0xfedcba9876543210ull, 0xf096a5b4c3b2e187ull
    };
    uint64_t x[8];
    size_t rest, total, i;

    tiger192_sboxes();

    for ( rest = len; rest >= 64; p += 64, rest -= 64 ) {
        tiger_decode( x, p );
        tiger_compress( h, x );
    }

    /* 0x01, zeros to 8 bytes short of a block, the bit count little-endian.  */
    total = rest < 56 ? 64 : 128;
    memset( last, 0, sizeof last );
    memcpy( last, p, rest );
    last[rest] = 0x01;
    for ( i = 0; i < 8; i++ )
        last[total - 8 + i] = (unsigned char)( bits >> ( 8 * i ) );

    tiger_decode( x, last );
    tiger_compress( h, x );
    if ( total == 128 ) {
        tiger_decode( x, last + 64 );
        tiger_compress( h, x );
    }

    for ( i = 0; i < 24; i++ )
        out[i] = (unsigned char)( h[i / 8] >> ( 8 * ( i % 8 ) ) );
}
